    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be printed in full (support tickets, logs).
SECRET_KEYS = frozenset({"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"})


def _parse_dotenv_line(line):
    """Return (key, value) for one dotenv line, or None if the line is not an assignment.

    Supports ``KEY=value``, an optional leading ``export ``, and values wrapped in
    matching single or double quotes. Only the first ``=`` separates key from value,
    so values may themselves contain ``=``.
    """
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    if line.startswith("export ") or line.startswith("export\t"):
        line = line[len("export"):].lstrip()
    if "=" not in line:
        return None
    key, value = line.split("=", 1)
    key = key.strip()
    value = value.strip()
    if not key:
        return None
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        value = value[1:-1]
    return key, value


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = _parse_dotenv_line(line)
            if parsed is not None:
                values[parsed[0]] = parsed[1]
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def redact(key, value):
    """Return a display-safe version of a setting value.

    Secrets keep only their first four characters so support can tell which
    credential is configured without the full value ending up in a ticket.
    """
    if value is None:
        return "(not set)"
    if key in SECRET_KEYS:
        return value[:4] + "..." + "(%d chars)" % len(value)
    return value


def format_doctor(config, dotenv_path=".env"):
    """Render the effective configuration as text suitable for a support ticket."""
    lines = []
    if os.path.exists(dotenv_path):
        lines.append(".env file: %s" % os.path.abspath(dotenv_path))
    else:
        lines.append(".env file: not found (%s)" % os.path.abspath(dotenv_path))
    lines.append("")
    width = max(len(key) for key in config)
    for key, (value, source) in config.items():
        lines.append("%-*s  %-8s  %s" % (width, key, source, redact(key, value)))
    lines.append("")
    lines.append("Secret values are redacted. Sources: env = process environment, "
